// Entscheidet UND formuliert in einem Schritt.
//
// Wer nicht gemeldet werden soll, erzeugt hier ein leeres Ergebnis — dann
// laeuft der Zweig einfach aus. Das ersetzt einen IF-Node, der falsch
// konfiguriert sein kann, durch eine Zeile Code, die man lesen kann.
//
// Warum ueberhaupt gefiltert wird: ipinfo liefert bei einem Privatanschluss den
// PROVIDER, nicht die Firma des Besuchers. "Deutsche Telekom AG" heisst nur,
// dass jemand einen Telekom-Anschluss hat. Bei einem Firmennetz mit eigenem AS
// steht dort der echte Name — und nur der ist einen Anruf wert.

// Der Webhook-Node legt die Nutzdaten unter "body" ab, nicht obenauf. Wer
// direkt $json.ereignis liest, bekommt undefined — der Filter unten verwirft
// dann JEDE Meldung, ohne Fehler und ohne roten Knoten. Genau das ist zweimal
// passiert: erst kam eine leere Mail, danach gar keine.
const roh = $input.first().json;
const d = roh.body ?? roh;

// Der Tagesbericht bringt seinen Text fertig mit und geht immer raus.
if (d.text) {
  return [{ json: { betreff: 'KITech-Website: Tagesbericht', nachricht: d.text } }];
}

const TITEL = {
  besuch: 'Firma auf der Website',
  termin_geoeffnet: 'Terminseite geoeffnet',
  popup_geklickt: 'Popup geklickt — will einen Call',
  telefon_geklickt: 'Telefonnummer geklickt',
  email_geklickt: 'E-Mail-Adresse geklickt',
  selbstcheck_fertig: 'Selbstcheck abgeschlossen',
};

// Jemand sucht aktiv Kontakt — das geht immer raus, egal woher er kommt.
const KONTAKT = ['telefon_geklickt', 'email_geklickt', 'popup_geklickt',
                 'termin_geoeffnet', 'selbstcheck_fertig'];

// Provider, Mobilfunk, Carrier: Privatanschluss.
const PRIVAT = ['deutsche telekom', 'telekom deutschland', 'vodafone', 'telefonica',
  'o2 ', '1&1', 'united internet', 'kabel deutschland', 'unitymedia', 'netcologne',
  'ewe tel', 'm-net', 'wilhelm.tel', 'htp gmbh', 'osnatel', 'versatel', 'plusnet',
  'pyur', 'tele columbus', 'congstar', 'drillisch', 'freenet', 'colt technology',
  'telenet', 'liberty global', 'orange', 'proximus', 'swisscom', 'a1 telekom',
  'magenta telekom', 'init7', 'sunrise'];

// Rechenzentren, Cloud, VPN: Bot oder anonymisiert.
const MASCHINEN = ['amazon', 'aws', 'google llc', 'google cloud', 'microsoft',
  'azure', 'hetzner', 'ovh', 'digitalocean', 'linode', 'vultr', 'cloudflare',
  'akamai', 'fastly', 'contabo', 'ionos', 'strato', 'netcup', 'scaleway',
  'oracle', 'alibaba', 'tencent', 'datacamp', 'm247', 'leaseweb', 'nordvpn',
  'mullvad', 'private internet', 'surfshark', 'protonvpn'];

const istKontakt = KONTAKT.includes(d.ereignis);
const firmaRoh = d.firma ? String(d.firma) : '';
const f = firmaRoh.toLowerCase();

let istEchteFirma = firmaRoh.length > 0;
if (istEchteFirma) {
  for (const w of PRIVAT)    if (f.includes(w)) { istEchteFirma = false; break; }
}
if (istEchteFirma) {
  for (const w of MASCHINEN) if (f.includes(w)) { istEchteFirma = false; break; }
}

// Nichts zu melden: leeres Ergebnis, der Zweig endet hier.
if (!istKontakt && !istEchteFirma) {
  return [];
}

// Der Firmenname steht nur oben, wenn es WIRKLICH eine Firma ist. Sonst waere
// bei einem Kontaktklick vom Privatanschluss "Website-Besuch: Deutsche Telekom
// AG" im Betreff — als haette der Konzern angerufen.
// AS-Nummer vorne abschneiden: "AS201011 Continental AG" -> "Continental AG"
const firma = istEchteFirma ? firmaRoh.replace(/^AS\d+\s+/, '') : '';

const zeilen = [];
zeilen.push(firma || (TITEL[d.ereignis] ?? d.ereignis));
zeilen.push('');

if (firma) {
  const ort = [d.ort, d.region].filter(Boolean).join(', ');
  if (ort) zeilen.push('Sitz laut Netz: ' + ort);
}

zeilen.push('Was: ' + (TITEL[d.ereignis] ?? d.ereignis));
if (d.seite) zeilen.push('Seite: ' + d.seite);
if (d.referrer) zeilen.push('Kam ueber: ' + d.referrer);

const kampagne = [d.utm_source, d.utm_medium, d.utm_campaign].filter(Boolean).join(' / ');
if (kampagne) zeilen.push('Kampagne: ' + kampagne);

if (d.zeitpunkt) {
  zeilen.push('');
  zeilen.push(new Date(d.zeitpunkt).toLocaleString('de-DE', { timeZone: 'Europe/Berlin' }));
}

if (firma) {
  zeilen.push('');
  zeilen.push('Suche: https://www.google.com/search?q=' + encodeURIComponent(firma));
}

const betreff = firma
  ? 'Website-Besuch: ' + firma
  : 'Website: ' + (TITEL[d.ereignis] ?? d.ereignis);

return [{ json: { betreff, nachricht: zeilen.join('\n') } }];
